<?php
namespace App\Domain\Workflow\Handlers;use App\Domain\Workflow\{ActionFailure,ActionHandler,ActionResult};use App\Services\TemplateRenderer;use Illuminate\Support\Facades\Mail;use InvalidArgumentException;
final class EmailNotificationAction implements ActionHandler{public function __construct(private TemplateRenderer $templates){}public function type():string{return 'email_notification';}public function validateConfig(array $c):void{if(empty($c['to'])||empty($c['subject']))throw new InvalidArgumentException('to and subject are required');}
 public function execute(array $c,array $context,string $idempotencyKey):ActionResult{$this->validateConfig($c);$to=(string)$this->templates->render($c['to'],$context);if(!filter_var($to,FILTER_VALIDATE_EMAIL))throw new ActionFailure('Invalid recipient','validation');$subject=(string)$this->templates->render($c['subject'],$context);$body=(string)$this->templates->render($c['body']??'',$context);try{Mail::raw($body,fn($m)=>$m->to($to)->subject($subject));}catch(\Throwable $e){throw new ActionFailure($e->getMessage(),'transient');}return new ActionResult(['email'=>['to'=>$to,'sent'=>true]]);}}
